insert into "monthly_market_calendar" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body", "is_published") values ('2026-05-01', 'ปฏิทินเศรษฐกิจเดือนพฤษภาคม 2569: จับตา Fed Chair ใหม่ ตัวเลข CPI และฤดูผลประกอบการ', '2026-05-01', 'ปฏิทินเศรษฐกิจเดือนพฤษภาคม 2569: จับตา Fed Chair ใหม่ ตัวเลข CPI และฤดูผลประกอบการ', 'ปฏิทินเศรษฐกิจและนัยต่อตลาดการเงิน พฤษภาคม 2569', '2026-05-01', '2026-05-01', '2026-05-31', NULL, 'พฤษภาคมนี้คับคั่งด้วยตัวเลขเศรษฐกิจชั้นนำ การประชุม G7 และฤดูกาลรายงานผลประกอบการที่ร้อนแรง — อย่าพลาดจุดเปลี่ยนสำคัญของตลาด', '<p><span>ในเดือนพฤษภาคม 2569 นักลงทุนควรจับตาเหตุการณ์สำคัญหลายจุด ได้แก่ ตัวเลข US CPI (12 พ.ค.) และ Core PCE (28 พ.ค.) ที่จะชี้ทิศทางนโยบายการเงิน Fed รวมถึงการสิ้นสุดวาระประธาน Powell ในวันที่ 15 พ.ค.</span></p><p><span>ฝั่งผลประกอบการบริษัทใหญ่อย่าง Nvidia (20 พ.ค.) Alibaba และ Tencent (13 พ.ค.) รวมถึง Walmart และ Salesforce ล้วนเป็นตัวชี้วัดทิศทางกำไรตลาดหุ้นโลก ขณะที่การพบกันระหว่าง Trump–Xi (14–15 พ.ค.) อาจส่งสัญญาณต่อสินทรัพย์จีนและห่วงโซ่อุปทานเทคโนโลยี</span></p>', '<h3><span>สรุปภาพรวมปฏิทินเศรษฐกิจ</span></h3><p><span>ในเดือนพฤษภาคม 2569 ปฏิทินเศรษฐกิจเต็มไปด้วยสัญญาณสำคัญที่นักลงทุนควรติดตามอย่างใกล้ชิด โดยเฉพาะตัวเลข US Nonfarm Payrolls (8 พ.ค.) US CPI (12 พ.ค.) และ Core PCE (28 พ.ค.) ซึ่งจะกำหนดทิศทางนโยบายการเงินของ Fed หลังจากวาระดำรงตำแหน่งของประธาน Powell สิ้นสุดลงในวันที่ 15 พ.ค. นอกจากนี้ การพบกันระหว่าง Trump–Xi ในวันที่ 14–15 พ.ค. และการประชุม G7 ระดับรัฐมนตรีหลายครั้งตลอดเดือนจะเป็นปัจจัยสำคัญต่อตลาดการเงินโลก ในขณะที่ฤดูกาลรายงานผลประกอบการยังคงดำเนินต่อเนื่องด้วยบริษัทชั้นนำอย่าง Nvidia, Alibaba, Tencent, Walmart และ Salesforce</span></p><div style=''overflow-x:auto;-webkit-overflow-scrolling:touch;''><table style=''width:100%;border-collapse:collapse;table-layout:fixed;font-family:''Noto Sans Thai'',sans-serif;font-size:12px;border:1px solid #d4d9e0;margin:10px 0;''><thead><tr><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Mon</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Tue</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Wed</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Thu</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Fri</th></tr></thead><tbody><tr><td style=''border:1px solid #e6e9ee;vertical-align:top;padding:7px 8px;line-height:1.4;''><span style=''font-weight:bold;color:#0c244a;font-size:13px;display:block;margin-bottom:3px;''>4</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>US Earnings: Palantir, ON Semi, Powell Industries, Grab, Duolingo</span></td><td style=''border:1px solid #e6e9ee;vertical-align:top;padding:7px 8px;line-height:1.4;''><span style=''font-weight:bold;color:#0c244a;font-size:13px;display:block;margin-bottom:3px;''>5</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>US: ISM Services</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>US: JOLTs</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>US Earnings: Shopify, Pfizer, Eaton, AMD, LITE, SMCI, ANET, ALAB, Navitas, AEP</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>EU Earnings: Ferrari</span></td><td style=''border:1px solid #e6e9ee;vertical-align:top;padding:7px 8px;line-height:1.4;''><span style=''font-weight:bold;color:#0c244a;font-size:13px;display:block;margin-bottom:3px;''>6</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>US: ADP Employment</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>Global: G7 Trade Minister Meeting</