'>JP: Tokyo CPI</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>IN: GDP 1Q26</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>Global: G7 Digital Minister Meeting</span></td></tr></tbody></table></div>', true);
insert into "monthly_market_calendar" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body", "is_published") values ('2026-06-01', 'ปฏิทินเศรษฐกิจเดือนมิถุนายน 2569: จับตา FOMC Dot Plot, ธนาคารกลางทั่วโลก และฤดูงาน Tech ระดับโลก', '2026-06-01', 'ปฏิทินเศรษฐกิจเดือนมิถุนายน 2569: จับตา FOMC Dot Plot, ธนาคารกลางทั่วโลก และฤดูงาน Tech ระดับโลก', 'ปฏิทินเศรษฐกิจและนัยต่อตลาดการเงิน มิถุนายน 2569', '2026-06-01', '2026-06-01', '2026-06-30', NULL, 'มิถุนายนนี้คับคั่งด้วยการประชุมธนาคารกลางสี่แห่งพร้อมกัน ตัวเลขเงินเฟ้อชุดใหญ่ และงาน Tech ระดับโลกที่อาจเขย่าตลาดหุ้นเทคโนโลยี', '<p><span>เดือนมิถุนายน 2569 เต็มไปด้วยเหตุการณ์สำคัญที่ต้องติดตามอย่างใกล้ชิด โดยไฮไลต์หลักคือการประชุม FOMC พร้อม Dot Plot ในวันที่ 18 มิถุนายน ซึ่งจะกำหนดทิศทางดอกเบี้ยสหรัฐฯ ต่อจากนั้น</span></p><p><span>นอกจากนี้ยังมีการประชุม ECB, BOE และ BOJ ในเดือนเดียวกัน ควบคู่กับตัวเลข CPI สหรัฐฯ, Core PCE และ Nonfarm Payrolls ที่จะกำหนดภาพรวมเงินเฟ้อและตลาดแรงงาน ขณะที่งาน COMPUTEX 2026 และ Apple WWDC จะเป็นตัวแปรสำคัญสำหรับกลุ่มหุ้น Tech อาทิ Nvidia, TSMC และ Apple</span></p>', '<h3><span>สรุปภาพรวมปฏิทินเศรษฐกิจ</span></h3><p><span>ในเดือนมิถุนายน 2569 ตลาดการเงินโลกต้องเผชิญกับปัจจัยเสี่ยงและโอกาสที่หนาแน่นที่สุดในรอบหลายเดือน เริ่มจากการประชุม FOMC พร้อม Dot Plot ในวันที่ 18 มิถุนายน ซึ่งตามมาด้วยการประชุม ECB (11 มิ.ย.), BOE (18 มิ.ย.), BOJ (16 มิ.ย.) และ RBI (5 มิ.ย.) ในฝั่งข้อมูลเศรษฐกิจ ตัวเลขสำคัญได้แก่ US Nonfarm Payrolls (5 มิ.ย.), US CPI (10 มิ.ย.), US Core PCE และ GDP 1Q26 Final (25 มิ.ย.) รวมถึง CN CPI (10 มิ.ย.) ขณะที่ภาคเทคโนโลยีมีงาน COMPUTEX 2026 (2–5 มิ.ย.), Apple WWDC 2026 (8 มิ.ย.) และ Nvidia Keynote at GTC Taipei (1 มิ.ย.) เป็นตัวเร่งสำคัญ พร้อมด้วยรายงานผลประกอบการจาก Broadcom, CrowdStrike, Oracle, Adobe และ Micron</span></p><div style=''overflow-x:auto;-webkit-overflow-scrolling:touch;''><table style=''width:100%;border-collapse:collapse;table-layout:fixed;font-family:''Noto Sans Thai'',sans-serif;font-size:12px;border:1px solid #d4d9e0;margin:10px 0;''><thead><tr><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Mon</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Tue</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Wed</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Thu</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Fri</th></tr></thead><tbody><tr><td style=''border:1px solid #e6e9ee;vertical-align:top;padding:7px 8px;line-height:1.4;''><span style=''font-weight:bold;color:#0c244a;font-size:13px;display:block;margin-bottom:3px;''>1</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>KR: Exports</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>Nvidia: Keynote at GTC Taipei</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>US: ISM Manufacturing</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>US Earnings: Credo, HPE</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>CN Earnings: Meituan</span></td><td style=''border:1px solid #e6e9ee;vertical-align:top;padding:7px 8px;line-height:1.4;''><span style=''font-weight:bold;color:#0c244a;font-size:13px;display:block;margin-bottom:3px;''>2</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>US: JOLTs</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>EA: CPI</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>US Earnings: Palo Alto, Ulta Beauty</span><span style=''display:block;color:#1a2e44;margin:1px 0;''>BofA Conference: AMD, Intel, LRCX, AMAT, AD