insert into "monthly_market_calendar" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body", "is_published") values ('2026-07-01', 'ปฏิทินเศรษฐกิจเดือนกรกฎาคม 2569: จับตา Fed, ECB, BOJ และฤดูผลประกอบการไตรมาส 2', '2026-07-01', 'ปฏิทินเศรษฐกิจเดือนกรกฎาคม 2569: จับตา Fed, ECB, BOJ และฤดูผลประกอบการไตรมาส 2', 'ปฏิทินเศรษฐกิจและนัยต่อตลาดการเงิน กรกฎาคม 2569', '2026-07-01', '2026-07-01', '2026-07-31', NULL, 'กรกฎาคมนี้ตลาดเดินเข้าสู่ฤดูผลประกอบการเต็มสตรีม พร้อมนัดชี้ชะตาจากธนาคารกลางสี่แห่งในคืนเดียว', '<p><span>ในเดือนกรกฎาคม 2569 นักลงทุนต้องติดตามการประชุมธนาคารกลางสำคัญพร้อมกันในช่วงปลายเดือน ได้แก่ Fed (30 ก.ค.), ECB (23 ก.ค.), BOE (30 ก.ค.) และ BOJ (31 ก.ค.) ซึ่งอาจสร้างความผันผวนในตลาดสกุลเงินและพันธบัตรพร้อมกัน</span></p><p><span>ด้านผลประกอบการ บริษัทเทคโนโลยีขนาดใหญ่อย่าง Apple, Amazon, Microsoft, Meta, Google และ TSMC รายงานในสัปดาห์สุดท้ายของเดือน ขณะที่ตัวเลขมหภาคสำคัญ เช่น US CPI (14 ก.ค.), GDP 2Q26 ทั้งของสหรัฐฯ และจีน รวมถึง Core PCE (30 ก.ค.) จะเป็นตัวกำหนดทิศทางตลาดในระยะสั้น</span></p>', '<h3><span>ปฏิทินเศรษฐกิจและเหตุการณ์สำคัญประจำเดือนกรกฎาคม 2569</span></h3><div style=''overflow-x:auto;-webkit-overflow-scrolling:touch;''><table style=''width:100%;border-collapse:collapse;table-layout:fixed;font-family:''Noto Sans Thai'',sans-serif;font-size:12px;border:1px solid #d4d9e0;margin:10px 0;''><thead><tr><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Mon</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Tue</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Wed</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px so